USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementTracking_GetStatuses
AS BEGIN SET NOCOUNT ON;SELECT STATUS_CODE,STATUS_NAME,DISPLAY_ORDER FROM dbo.PROCUREMENT_STATUS_MASTER WHERE IS_ACTIVE=1 ORDER BY DISPLAY_ORDER,STATUS_NAME;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementTracking_Search @RequisitionNo VARCHAR(30)=NULL,@OrgUnitId BIGINT=NULL,@AssetId BIGINT=NULL,@StatusCode VARCHAR(40)=NULL
AS BEGIN SET NOCOUNT ON;SELECT p.PROCUREMENT_ID,h.REQUISITION_ID,h.REQUISITION_NO,o.ORG_UNIT_NAME,(SELECT STRING_AGG(CONVERT(NVARCHAR(MAX),a.ASSET_NAME),N', ')WITHIN GROUP(ORDER BY a.ASSET_NAME)FROM(SELECT DISTINCT am.ASSET_NAME FROM dbo.REQUISITION_ITEM ri JOIN dbo.ASSET_MASTER am ON am.ASSET_ID=ri.ASSET_ID WHERE ri.REQUISITION_ID=h.REQUISITION_ID AND ri.IS_ACTIVE=1)a)ASSETS,s.STATUS_CODE,s.STATUS_NAME,p.PROCUREMENT_REFERENCE_NO,p.MODIFIED_DATE FROM dbo.PROCUREMENT_TRACKING p JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=p.REQUISITION_ID JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=p.CURRENT_STATUS_ID WHERE(@RequisitionNo IS NULL OR h.REQUISITION_NO LIKE @RequisitionNo+'%')AND(@OrgUnitId IS NULL OR h.REQUESTED_ORG_UNIT_ID=@OrgUnitId)AND(@StatusCode IS NULL OR s.STATUS_CODE=@StatusCode)AND(@AssetId IS NULL OR EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.ASSET_ID=@AssetId AND i.IS_ACTIVE=1))ORDER BY p.MODIFIED_DATE DESC;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementTracking_GetDetail @RequisitionId BIGINT
AS BEGIN SET NOCOUNT ON;SELECT p.PROCUREMENT_ID,h.REQUISITION_ID,h.REQUISITION_NO,o.ORG_UNIT_NAME,s.STATUS_CODE,s.STATUS_NAME,p.PROCUREMENT_REFERENCE_NO,p.REMARKS FROM dbo.PROCUREMENT_TRACKING p JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=p.REQUISITION_ID JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=p.CURRENT_STATUS_ID WHERE h.REQUISITION_ID=@RequisitionId;SELECT ph.STATUS_HISTORY_ID,s.STATUS_CODE,s.STATUS_NAME,ph.STATUS_DATE,ph.REFERENCE_NO,ph.CHANGED_BY_EMPLOYEE_ID,ph.REMARKS,ph.BATCH_REFERENCE_ID FROM dbo.PROCUREMENT_STATUS_HISTORY ph JOIN dbo.PROCUREMENT_TRACKING p ON p.PROCUREMENT_ID=ph.PROCUREMENT_ID JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=ph.STATUS_ID WHERE p.REQUISITION_ID=@RequisitionId ORDER BY ph.STATUS_DATE,ph.STATUS_HISTORY_ID;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementTracking_UpdateStatus @RequisitionId BIGINT,@StatusCode VARCHAR(40),@StatusDate DATETIME2(3),@ActorEmployeeId VARCHAR(30),@ReferenceNo VARCHAR(100)=NULL,@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;DECLARE @pid BIGINT,@sid BIGINT,@currentDate DATETIME2(3);SELECT @pid=PROCUREMENT_ID FROM dbo.PROCUREMENT_TRACKING WITH(UPDLOCK,HOLDLOCK)WHERE REQUISITION_ID=@RequisitionId;SELECT @sid=STATUS_ID FROM dbo.PROCUREMENT_STATUS_MASTER WHERE STATUS_CODE=@StatusCode AND IS_ACTIVE=1;IF @pid IS NULL THROW 51001,'Procurement tracking was not found.',1;IF @sid IS NULL THROW 51000,'Procurement status code is invalid or inactive.',1;IF @StatusDate IS NULL OR @StatusDate>DATEADD(MINUTE,5,SYSUTCDATETIME())THROW 51000,'Status date is required and cannot be in the future.',1;SELECT @currentDate=MAX(STATUS_DATE)FROM dbo.PROCUREMENT_STATUS_HISTORY WHERE PROCUREMENT_ID=@pid;IF @currentDate IS NOT NULL AND CONVERT(DATE,@StatusDate)<CONVERT(DATE,@currentDate)THROW 51000,'Status date cannot be earlier than the latest recorded status date.',1;IF @currentDate IS NOT NULL AND @StatusDate<=@currentDate SET @StatusDate=DATEADD(MILLISECOND,1,@currentDate);UPDATE dbo.PROCUREMENT_TRACKING SET CURRENT_STATUS_ID=@sid,PROCUREMENT_REFERENCE_NO=COALESCE(NULLIF(LTRIM(RTRIM(@ReferenceNo)),''),PROCUREMENT_REFERENCE_NO),REMARKS=@Remarks,MODIFIED_DATE=SYSUTCDATETIME()WHERE PROCUREMENT_ID=@pid;INSERT dbo.PROCUREMENT_STATUS_HISTORY(PROCUREMENT_ID,STATUS_ID,STATUS_DATE,REFERENCE_NO,CHANGED_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID)VALUES(@pid,@sid,@StatusDate,NULLIF(LTRIM(RTRIM(@ReferenceNo)),''),@ActorEmployeeId,@Remarks,@BatchReferenceId);UPDATE dbo.REQUISITION_HEADER SET CURRENT_STATUS=CASE WHEN @StatusCode='READY_FOR_PROCUREMENT'THEN'READY_FOR_PROCUREMENT'WHEN @StatusCode='PROCUREMENT_COMPLETED'THEN'COMPLETED'ELSE'PROCUREMENT_IN_PROGRESS'END,MODIFIED_BY=@ActorEmployeeId,MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId;COMMIT;SELECT'000'RESULT_CODE,N'Success'RESULT_MESSAGE,@RequisitionId ENTITY_ID,@StatusCode REFERENCE_NO;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SELECT CASE ERROR_NUMBER()WHEN 51000 THEN'001'WHEN 51001 THEN'002'ELSE'999'END RESULT_CODE,ERROR_MESSAGE()RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;END CATCH END;
GO
